    if (d > 3.5) {
      const r = await api.reachable(p[0], p[1], p[2]);
      if (!r.reachable && r.status !== 'timeout') continue;
      try { await api.goto(p[0], p[1], p[2], 2); } catch (e) {}
    }
    for (let a = 0; a < 3; a++) {
      try {
        await api.look(p[0]+.5, p[1]+.5, p[2]+.5);
        await api.open(p[0], p[1], p[2]);
        await api.deposit(item);
        await api.wait(3);
      } catch (e) { await api.wait(5); }
      try { if (api.window()) await api.close(); } catch (e) {}
      if (!(api.inventory()[item] > 0)) return 'done';
    }
  }
  return 'stuck';
}
